import math

def _rendezvous_slot_intervals(sandbox):
    return sandbox.get_rendezvous_slots()

def build_agent(sandbox):
    return sandbox.get_seeker_body()

def agent_action(sandbox, agent_body, step_count):
    if not hasattr(agent_body, '_state'):
        agent_body._state = {
            'last_tx': 0.0, 'last_ty': 0.0,
            'tvx': 0.0, 'tvy': 0.0,
            'activation_streak': 0,
            'activated': False
        }

    state = agent_body._state
    tx, ty = sandbox.get_target_position()
    sx, sy = sandbox.get_seeker_position()
    svx, svy = sandbox.get_seeker_velocity()

    # Update activation streak
    if 13.0 <= sx <= 17.0:
        state['activation_streak'] += 1
    else:
        state['activation_streak'] = 0
    if state['activation_streak'] >= 80:
        state['activated'] = True

    # Estimate target velocity
    if step_count % 5 == 0 and step_count > 5:
        dt = 5.0 / 60.0
        state['tvx'] = 0.5 * state['tvx'] + 0.5 * (tx - state['last_tx']) / dt
        state['tvy'] = 0.5 * state['tvy'] + 0.5 * (ty - state['last_ty']) / dt
        state['last_tx'], state['last_ty'] = tx, ty
    elif step_count <= 5:
        state['last_tx'], state['last_ty'] = tx, ty

    # Get rendezvous slots
    slots = _rendezvous_slot_intervals(sandbox)
    in_slot = any(lo <= step_count <= hi for (lo, hi) in slots)

    x_min, x_max = sandbox.get_corridor_bounds()

    if not state['activated']:
        # Activation phase: move to center of corridor, clamped to activation zone
        goal_x = (x_min + x_max) / 2
        goal_x = max(13.0, min(goal_x, 17.0))
        goal_y = 1.35  # Safe y-position to avoid ground or obstacles

        fx = 200.0 * (goal_x - sx) - 50.0 * svx
        fy = 100.0 * (goal_y - sy) - 25.0 * svy

    else:
        # Activated phase: proceed with rendezvous and tracking
        if in_slot:
            # Rendezvous slot: track target, but within corridor
            goal_x = max(x_min + 0.1, min(tx, x_max - 0.1))
            goal_y = ty
            fx = 300.0 * (goal_x - sx) + 60.0 * (state['tvx'] - svx)
            fy = 300.0 * (goal_y - sy) + 60.0 * (state['tvy'] - svy)
        else:
            # Non-slot phase: track target but stay within corridor
            goal_x = max(x_min + 0.1, min(tx, x_max - 0.1))
            goal_y = 1.35  # maintain safe y
            fx = 300.0 * (goal_x - sx) - 60.0 * svx
            fy = 180.0 * (goal_y - sy) - 45.0 * svy

        # Ensure sufficient thrust if near target
        if in_slot and step_count >= 110 and abs(goal_x - sx) > 0.05:
            if abs(fx) < 110.0:
                fx = 110.0 if (goal_x - sx) > 0 else -110.0

    # Cap thrust to avoid cooldown
    mag = math.sqrt(fx**2 + fy**2)
    if mag > 189.0:
        fx, fy = fx * 189.0 / mag, fy * 189.0 / mag

    sandbox.apply_seeker_force(fx, fy)
